  'settings.connections.type': 'Jenis',
  'settings.connections.typeHint': '“Tiada” dan “Terus” bukan baris yang sama. Tiada bersifat lengai: ia tidak menamakan sebarang sambungan dan tidak pernah digunakan, jadi ia hanya bertahan sehingga anda selesai mengisinya. Terus ialah pilihan sebenar - keluar melalui talian mesin ini sendiri dan sengaja memintas setiap proksi bagi hos yang dinamakan di bawah, itulah caranya sebuah NAS dikecualikan daripada proksi yang meliputi seluruh aplikasi. Baris yang penapisnya sepadan dengan hos mengatasi baris tanpa penapis, jadi baris terus berpenapis sentiasa menang berbanding proksi yang menyambar semuanya.',
