  'settings.rules.thenHintFilter': 'Peraturan yang menolak menahan pautan bersama sebabnya. Peraturan yang menerima juga berbaloi: diletak di atas penolakan luas, dengan «berhenti pada padanan pertama» dihidupkan, begitulah satu hos tunggal dilepaskan.',
