  'settings.rules.patternHint': 'Ungkapan biasa Go, tanpa sauh, dan satu-satunya operator yang TIDAK mengabaikan huruf besar kecil - letak (?i) di hadapan jika anda mahu ia mengabaikannya. Corak yang tidak terbaca ditolak berserta sebabnya, bukannya senyap-senyap berhenti padan dengan apa-apa.',
