  'settings.rules.yes': 'Hidup',
  'settings.rules.no': 'Mati',
  'settings.rules.reject': 'Tolak pautan',
  'settings.rules.accept': 'Terima pautan',
  'settings.rules.priorityHint': 'Lebih tinggi berjalan lebih awal. Julatnya ialah julat yang diterima baris gilir itu sendiri, jadi satu peraturan tidak boleh memberi tugasan keutamaan yang anda tiada cara untuk membatalkannya. Biar kosong supaya tiada apa berubah.',
