  'settings.reconnect.offState': 'Sambung semula dimatikan. Tiada apa-apa yang meminta alamat baharu daripada penghala, dan had hoster diserahkan kepada jeda cuba semula yang biasa.',

  'settings.reconnect.command': 'Program',
  'settings.reconnect.commandHint': 'Laluan penuh program yang akan dijalankan. Ia dimulakan terus dan bukan melalui shell, jadi paip, pengalihan atau dua perintah berturut-turut tempatnya dalam kaedah “Skrip”. %%router%%, %%username%%, %%password%% dan %%ip%% diisi sebelum ia bermula.',
  'settings.reconnect.args': 'Argumen',
