  'settings.reconnect.upnpState': 'Tiada apa-apa lagi diperlukan. Get laluan ditemui dengan bertanya kepada rangkaian, dan itulah yang menjadikan kaedah ini berfungsi tanpa mengetahui apa-apa tentang penghala.',
  'settings.reconnect.upnpLocation': 'URL perihalan get laluan',
  'settings.reconnect.upnpLocationHint': 'Pilihan, dan biasanya dibiarkan kosong. Isikan hanya di tempat carian multicast ditapis sedangkan get laluan itu sendiri boleh dicapai dengan baik, keadaan yang tidak akan pernah dapat dibetulkan oleh penemuan automatik semata-mata.',

  'settings.reconnect.interpreter': 'Pentafsir',
  'settings.reconnect.interpreterHint': 'Program yang menerima skrip itu, dengan laluan penuhnya: /bin/sh, /bin/bash, /usr/bin/python3.',
  'settings.reconnect.interpreterArgs': 'Argumen pentafsir',
  'settings.reconnect.interpreterArgsHint': 'Satu setiap baris, diletakkan sebelum fail skrip. Selalunya kosong.',
  'settings.reconnect.script': 'Skrip',
  'settings.reconnect.scriptHint': 'Ia ditulis ke fail sementara peribadi, dan pentafsir hanya diberi laluannya, jadi tiada apa-apa dari sini yang pernah berakhir dalam tanda petik pada baris perintah. Pemboleh ubah diisi sebelum fail ditulis, bermakna kata laluan yang anda taip dalam kotak ini turut sampai ke fail itu: dengan %%password%% ia kekal dalam medan kata laluan.',

  'settings.reconnect.router': 'Alamat penghala',
  'settings.reconnect.routerHint': 'Penghala dalam rangkaian anda sendiri, tanpa skema: 192.168.1.1, bukan http://192.168.1.1/. Itulah yang menjadi isi %%router%%. Ia bukan alamat awam, dan kedua-duanya jangan sekali-kali ditukar ganti: permintaan log masuk yang dihalakan ke alamat awam menghantar kata laluan penghala anda ke internet.',
