  'settings.reconnect.passwordHint': 'Kata laluan yang tersimpan tidak pernah dihantar semula ke halaman ini, sebab itulah kotaknya kosong: biarkan kosong dan yang tersimpan akan dikekalkan. Taip yang baharu untuk menggantikannya. Untuk membuangnya terus, taip apa-apa sahaja kemudian kosongkan semula kotak itu.',

