  'settings.reconnect.checkTitle': 'Menyemak alamat',
  'settings.reconnect.checkUrl': 'URL semakan IP',
  'settings.reconnect.checkUrlHint': 'Diambil sebelum kaedah dijalankan dan sekali lagi selepasnya; larian dikira selesai sebaik sahaja alamat yang dipaparkannya berubah. Sengaja tiada nilai lalai: pengurus muat turun yang anda hoskan sendiri tidak sepatutnya mula melaporkan alamat anda kepada perkhidmatan yang tidak pernah anda pilih. Apa yang dipaparkan mestilah alamat yang dilihat oleh internet, kerana halaman yang memulangkan alamat dalam rangkaian anda sendiri tidak dapat membezakan sambung semula daripada tiada apa-apa berlaku.',
  'settings.reconnect.checkPresets': 'Perkhidmatan yang dikenali',
  'settings.reconnect.checkPresetsHint': 'Jalan pintas untuk sesiapa yang tiada pilihan tertentu, bukan nilai lalai: tiada satu pun dipilihkan untuk anda, dan mana-mana halaman yang memaparkan alamat awam anda melakukan kerja yang sama baiknya.',
  'settings.reconnect.interval': 'Saat antara semakan (1 hingga 60)',
