  'settings.chunks': 'Sambungan bagi setiap muat turun (0 = automatik)',
  'settings.chunksHint': 'Berapa sambungan dibuka oleh satu muat turun apabila tiada yang lebih khusus terpakai. Satu peraturan, atau satu muat turun, boleh menyebut nombornya sendiri dan mengatasi nombor ini. Hos yang hanya tahan lebih sedikit tetap mendapat lebih sedikit: had hos hanya boleh menurunkan nombor itu, tidak sekali-kali menaikkannya. Dengan 0 aplikasi yang memutuskan. Melebihi segenggam sambungan tidak memberi apa-apa pada hos yang mengehadkan setiap fail, dan ia cara pasti untuk sesebuah akaun ditanda.',
  'task.chunks': 'Sambungan (0 = tetapan global)',
  'task.chunksHint': 'Berapa sambungan dibuka oleh muat turun yang satu ini. Ia mengatasi tetapan global dan mana-mana peraturan yang menetapkannya, tetapi tidak sekali-kali mengatasi hos: hos yang hanya tahan lebih sedikit tetap mendapat lebih sedikit. Dengan 0 pengecualian ditarik dan nombornya kembali diputuskan di luar.',
  'columns.connection': 'Sambungan',

  'props.title': 'Sifat',
  'props.mixed': 'Beberapa nilai',
  'props.mixedHint': 'Baris-baris ini tidak sepadan, jadi kotaknya kosong. Jika tidak disentuh ia tidak mengubah apa-apa; taip di dalamnya dan setiap baris terpilih mendapat apa yang anda taip.',
  'props.name': 'Nama',
  'props.nameHint': 'Satu nama fail, tidak sekali-kali laluan: apa-apa yang mengeja folder dipangkas kepada satu nama sahaja. Muat turun yang telah siap turut dinamakan semula pada cakera, supaya senarai dan folder tidak boleh bercanggah. Yang sedang berjalan mengekalkan fail yang dibuka oleh backend-nya dan mengambil nama baharu apabila siap. Yang belum bermula mengambilnya serta-merta. Satu nama milik satu fail, jadi kotak ini hanya ditawarkan untuk satu baris.',
  'props.comment': 'Nota',
  'props.commentHint': 'Nota anda sendiri tentang pautan ini. Ia disimpan dan dipaparkan dalam senarai; tiada apa dalam apl yang bertindak berdasarkannya.',
  'props.priority': 'Keutamaan',
  'props.priorityHint': 'Yang lebih tinggi berjalan dahulu. Ia menyusun semula apa yang masih menunggu; muat turun yang sudah berjalan tidak dihantar balik ke baris gilir.',
  'props.autoExtract': 'Nyahzip arkib',
  'props.autoExtractHint': 'Sama ada arkib dibuka selepas muat turun selesai. „Warisi“ menyerahkan keputusan kepada halaman tetapan arkib, dan itu bukan sama dengan mati. Suis dibaca pada masa pembukaan, jadi menghidupkannya sekarang turut membuka sesuatu yang siap lebih awal.',
  'props.inherit': 'Warisi',
  'props.on': 'Hidup',
  'props.off': 'Mati',

  'strip.label': 'Jumlah muat turun',
