  'strip.hint': 'Bait yang diambil berbanding bait yang masih terhutang. Pautan yang siap, gagal dan sekadar dikumpul kekal di luar jumlah, begitu juga apa-apa yang saiznya belum dinyatakan oleh hos - tekaan di situ hanya menjadi nombor yang tiada siapa boleh guna.',
  'strip.scope': 'Apa yang angka ini merangkumi',
