  'settings.scripts.trigger.taskFailed': 'Muat turun gagal',
  'settings.scripts.trigger.queueIdle': 'Baris gilir menjadi terbiar',
  'settings.scripts.use': 'Aktifkan skrip ini',
  'settings.scripts.code': 'Kod',
  'settings.scripts.codeStarter':
    '// Skrip ini berjalan pada pencetus yang dipilih di atas.\n// API sandbox yang menjadi tempat ia berjalan masih dalam penyiapan - lihat Tetapan › Bantuan sebaik sahaja tersedia.\n',
  'settings.scripts.timeout': 'Had masa',
