  'settings.nav.resolvers': 'Penyelesai',
  'settings.module.ytdlp': 'yt-dlp',
  'settings.resolvers.moduleUnavailable': 'Modul tidak tersedia',
  'settings.resolvers.moduleUnavailableHint': 'Semua yang di bawah tetap disimpan dan berkuat kuasa sebaik sahaja yt-dlp tersedia - mengeditnya sekarang tidak akan menghilangkan apa-apa.',
  'settings.resolvers.intro': 'Konfigurasi untuk backend yt-dlp, yang mengambil laman media dan penstriman yang disokong oleh yt-dlp sendiri. Perkhidmatan mana yang mengendalikan sesuatu pautan - yt-dlp, akaun debrid, sidecar JD tanpa antara muka - ditentukan oleh susunan penghalaan pada halaman Akaun; di sini hanya diterangkan apa yang dilakukan yt-dlp selepas pautan sudah dihalakan kepadanya.',
  'settings.resolvers.quality': 'Kualiti',
  'settings.resolvers.qualityHint': 'Pemilih -f mana yang digunakan semasa memulakan yt-dlp. Terbaik tersedia ialah nilai lalai yt-dlp sendiri, dan yang digunakan oleh setiap muat turun sebelum tetapan ini wujud.',
  'settings.resolvers.quality.best': 'Terbaik tersedia',
