  'settings.resolvers.customFormatHint': 'Nilai -f milik yt-dlp sendiri, cth. bestvideo[height<=720]+bestaudio/best. Dihantar terus tanpa semakan; nilai yang ditolak oleh yt-dlp akan gagal dengan ralatnya sendiri pada tugas itu.',
