  'settings.torrents.uploadLimitHint': 'Mengehadkan kelajuan torrent memuat naik ke kelompok semasa melakukan seed. 0 = tanpa had.',
  'settings.torrents.uploadLimitUnit': 'KiB/s',
  'settings.torrents.portTitle': 'Port dan pemetaan',
  'settings.torrents.port': 'Port',
  'settings.torrents.portHint': 'Port tempat instans ini mendengar sambungan kelompok. 0 membiarkan enjin torrent memilih sendiri.',
  'settings.torrents.portMapHint': 'Meminta penghala meneruskan port di atas ke mesin ini melalui UPnP, supaya rakan sebaya di sebalik penghala lain masih boleh menjangkaunya. Bukan semua penghala menyokong ini, dan sesetengahnya menerima permintaan tanpa ia benar-benar berfungsi.',
  'settings.torrents.portMapButton': 'Cuba pemetaan UPnP',
  'settings.torrents.portMapping': 'Bertanya kepada penghala…',
  'settings.torrents.portMapNeedsPort': 'Tetapkan port di atas dahulu sebelum memetakannya - pada 0, penghala tiada destinasi untuk diteruskan.',
  'settings.torrents.portMapConfirmed': 'Disahkan: port {port} telah dipetakan dan disahkan boleh dicapai.',
  'settings.torrents.portMapUnconfirmed': 'Penghala menerima permintaan, tetapi tidak dapat disahkan bahawa pemetaan benar-benar berfungsi. Sesetengah penghala melakukan ini secara senyap - cuba semakan ketersambungan dari luar rangkaian.',
  'settings.torrents.portMapFailed': 'Tidak dapat memetakan port: {error}',
  'settings.torrents.portMapUnavailable': 'Build ini belum menawarkan pemetaan port.',
  'settings.torrents.networkTitle': 'Penemuan rakan sebaya',
  'settings.torrents.dht': 'DHT',
  'settings.torrents.dhtHint': 'Mencari rakan sebaya tanpa sebarang penjejak, dengan menggunakan klien BitTorrent lain sebagai direktori teragih.',
  'settings.torrents.pex': 'Pertukaran rakan sebaya (PEX)',
  'settings.torrents.pexHint': 'Menukar rakan sebaya yang diketahui dengan yang sudah bersambung, supaya kelompok dengan sedikit rakan sebaya ditemui lebih cepat.',
  'settings.torrents.privateNote': 'Torrent persendirian mematikan kedua-duanya secara automatik sebaik sahaja metadatanya diketahui, tidak kira apa tetapan di sini - serta-merta untuk fail .torrent yang dimuat naik, atau sebaik sahaja metadata pautan magnet itu sendiri tiba daripada kelompok. Kebanyakan penjejak persendirian menyekat akaun yang menggunakan mana-mana satu daripadanya.',
  'settings.torrents.engineNote': 'Sasaran nisbah seed, sasaran tempoh seed dan port kini terpakai pada setiap torrent yang dimulakan oleh enjin ini - port pula hanya untuk torrent pertama sejak but semula terakhir instans ini, kerana klien torrent enjin itu sendiri dibina sekali sahaja dan tidak pernah dibina semula selepas itu; simpanan yang dibuat kemudian tetap disimpan dengan betul dan berkuat kuasa mulai but semula seterusnya. Had muat naik masih hanya disimpan dan disahkan sahaja, tanpa sebarang cara buat masa ini bagi enjin untuk menerapkannya pada muat turun yang sedang berjalan. DHT dan PEX di bawah berada dalam keadaan yang sama bagi torrent biasa (bukan persendirian): nilai lalai instans ini sendiri juga masih belum sampai ke muat turun yang sedang berjalan, jadi torrent terus melakukan seed dengan kedua-duanya hidup tidak kira apa tetapan di sini - torrent persendirian adalah kes yang sama sekali berbeza, lihat nota di bawah. Namun, butang pemetaan di bawah tetap melakukan sesuatu yang nyata: ia meminta penghala secara jujur meneruskan nombor port yang dimasukkan di atas, sama ada terdapat torrent yang sedang mendengar di situ sekarang atau tidak.',
