  'onboarding.next': 'Seterusnya',
  'onboarding.finish': 'Mula guna KnightLoader',
  'onboarding.welcome.title': 'Selamat datang ke KnightLoader',
  'onboarding.welcome.body': 'KnightLoader ialah pengurus muat turun self-hosted: tampal atau lepaskan pautan, dan ia diambil oleh backend yang benar-benar mengendalikannya - enjin terbina dalam untuk pautan fail biasa, yt-dlp untuk halaman media, perkhidmatan debrid untuk hoster yang anda sudah bayar, atau JDownloader tanpa antara muka untuk selebihnya. Lawatan ringkas ini merangkumi satu-satunya tetapan yang berbaloi disemak sebelum anda mula.',
  'onboarding.welcome.langLabel': 'Bahasa antara muka',
  'onboarding.folder.title': 'Ke mana fail patut disimpan?',
  'onboarding.folder.body': 'Ini ialah folder tempat muat turun yang selesai ditulis. Taip laluan atau layari pelayan untuk memilih satu - anda boleh menukarnya semula bila-bila masa dari halaman tetapan Umum.',
  'onboarding.accounts.title': 'Hoster premium, bila-bila masa anda mahu',
  'onboarding.accounts.body': 'Baris gilir berfungsi tanpa sebarang akaun. Apabila anda mahukan kelajuan penuh pada hoster atau perkhidmatan debrid yang anda sudah bayar, tambah log masuknya di bawah Akaun - tiada apa perlu disediakan di sini sekarang.',
  'onboarding.accounts.link': 'Buka Akaun',
  'onboarding.finished.title': 'Anda sudah bersedia',
  'onboarding.finished.body': 'Dengan itu tamatlah lawatan ini. Halaman Bantuan di bawah Tetapan mempunyai penerangan lengkap tentang semua perkara lain yang dilakukan oleh binaan ini, dan kebanyakan kawalan membawa penjelasan sendiri di sebalik ikon (i).',

