  'settings.categories.emptyHint': 'Kategori memegang satu folder dan beberapa nilai lalai di bawah satu nama, jadi anda memilih nama itu dan bukannya menerangkan perkara yang sama sekali lagi.',
  'settings.categories.duplicate': 'Sudah ada kategori dengan nama ini.',
