  'settings.resolvers.presetHost': 'Hoster',
  'settings.resolvers.presetHostHint': 'Laman yang menjadi tempat nilai lalai ini terpakai, contohnya youtube.com. Ia disimpan dalam huruf kecil dan tanpa “www.” di hadapan, dan menampal alamat penuh juga boleh: hanya hosnya yang disimpan. Hoster tanpa entri di sini memulakan setiap varian dalam keadaan hidup, pada kualiti terbaik.',
