  'settings.feeds.seededHint': 'Semakan pertama bagi langganan baharu mencatat semua yang dibawa feed itu pada saat itu dan tidak menambah satu pun daripadanya, supaya seluruh arkib lama penerbit tidak jatuh kepada anda sekali gus. Hanya yang muncul selepas itu ditambah.',
  'settings.feeds.remembered': '{n} entri diingati',
