  'settings.headerProfiles.title': 'Profil header',
  'settings.headerProfiles.hint': 'Sesetengah laman hanya menyerahkan fail kepada pelayar yang sudah log masuk, atau hanya apabila panggilan itu datang daripada salah satu halaman mereka sendiri. Satu profil menyimpan header bagi tepat satu laman, disulitkan sama seperti kelayakan akaun anda, dan KnightLoader menghantarnya bersama setiap muat turun dari laman itu.',
  'settings.headerProfiles.empty': 'Belum ada profil header.',
  'settings.headerProfiles.emptyHint': 'Satu profil berbaloi sebaik sahaja sesuatu muat turun hanya menjadi selagi anda log masuk dalam pelayar.',
