  'settings.rules.action.category': 'Kategori',
  'settings.rules.action.categoryHint': 'Memfailkan pautan yang sepadan ke dalam salah satu laci dari halaman Kategori, yang membawa foldernya sendiri, tempatnya dalam baris gilir, suis nyahzipnya dan peraturan perlanggarannya sekali. Dibiarkan tidak berubah, tiada peraturan yang berpendapat tentangnya dan pautan itu kekal tidak difailkan. Jika peraturan ini turut menamakan folder muat turun, folder itu menang dan laci itu tetap membekalkan segala yang lain. Menamakan laci yang sudah dipadam ditolak semasa anda menyimpan, kerana peraturan yang menunjuk kepada laci yang tiada di situ langsung tidak melakukan apa-apa pada setiap pautan yang sepadan dengannya, tanpa sebarang mesej.',
  'settings.rules.action.categoryNone': 'Belum ada kategori. Cipta satu di halaman Kategori dahulu, jika tidak peraturan ini akan memfailkan pautan ke dalam laci yang tidak wujud.',
  'settings.rules.action.categoryMissing': '{id} (dipadam)',

