  'detail.label': 'Butiran tugasan',
  'detail.link': 'Pautan',
  'detail.address': 'Alamat',
  'detail.addressHint': 'Alamat yang menjadi tempat muat turun ini dimulakan. Itulah yang diminta oleh aplikasi, dan itu bukan selalunya tempat bait-bait itu datang: melalui perkhidmatan debrid, hoster di bawah ialah laman tempat fail itu berada, dan backend ialah siapa yang mengambilnya.',
  'detail.copy': 'Salin',
  'detail.copied': 'Disalin',
  'detail.copyFailed': 'Tiada apa-apa disalin.',
  'detail.origin': 'Masuk melalui',
