  'detail.package': 'Pakej',
  'detail.noPackage': 'Tiada dalam pakej',
  'detail.onDisk': 'Pada cakera sekarang',
  'detail.onDiskHint': 'Berapa besar fail itu pada cakera saat ini, ditanya kepada pelayan dan bukan dikira di sini. Muat turun yang sedang berjalan membesar antara satu pandangan dan pandangan berikutnya, dan ini bukan saiz yang diumumkan oleh hoster.',
  'detail.mirrorOf': 'Salinan ganti bagi',
  'detail.times': 'Cap masa',
  'detail.timesHint': 'Bila pautan ini tiba, bila ia terakhir berubah, dan bila ia selesai. Tiada masa untuk bila pemindahan itu bermula: aplikasi tidak pernah mencatatnya, dan tekaan daripada tiga yang lain itu akan menjadi nombor yang orang bertindak atasnya.',
  'detail.nextTry': 'Percubaan seterusnya',
  'detail.stalledSince': 'Terhenti sejak',
  'detail.retries': 'Cubaan semula setakat ini',
  'detail.retriesHint': 'Berapa kali muat turun ini dicuba semula selepas gagal. Ia ditetapkan semula kepada sifar sebaik sahaja muat turun itu selesai, jadi baris yang siap memaparkan sifar walaupun ia mengambil empat kali percubaan. Berapa banyak percubaan yang berbaki tidak dipaparkan: silingnya bergantung pada punca dan pada hoster, dan halaman ini tidak dapat mengiranya.',
  'detail.stallRestarts': 'Mula semula selepas terhenti',
  'detail.stallRestartsHint': 'Berapa kali pengawas keterhentian memulakan semula muat turun ini dengan sendirinya. Ia ditetapkan semula kepada sifar apabila muat turun itu selesai, sama seperti pembilang di atas.',
  'detail.failure': 'Apa yang tidak kena',
  'detail.cause': 'Punca',
  'detail.message': 'Apa yang dikatakan backend',
  'detail.messageHint': 'Ayat daripada apa jua yang cuba mengambil ini, perkataan demi perkataan dan tidak diterjemahkan. Ia kegagalan semasa dan tiada apa-apa lagi: mula semula mengosongkannya, dan yang terdahulu tidak disimpan di mana-mana.',
  'detail.heldBack': 'Ditahan oleh',
  'detail.doing': 'Sedang dilakukan',
  'detail.filtered': 'Ditahan oleh penapis pautan',
  'detail.gaveUp': 'Tiada percubaan lagi',
  'detail.gaveUpHint': 'Yang ini berhenti dengan sengaja, bukan kerana percubaannya sudah habis: satu captcha, cakera yang penuh, atau peraturan yang berkata jangan sekali-kali untuk hoster ini. Menaikkan bilangan cubaan semula tidak mengubah apa-apa di sini. Tanda itu sendiri tidak ditulis ke dalam pangkalan data, jadi ia hilang selepas mula semula walaupun sebabnya tidak.',
  'detail.rules': 'Peraturan yang membentuk ini',
  'detail.rulesHint': 'Peraturan yang tercetus pada pautan ini semasa ia disediakan, mengikut susunan ia berjalan. Ia disimpan mengikut nama, jadi peraturan yang telah dinamakan semula sejak itu tidak lagi dijumpai, dan peraturan yang tidak pernah mempunyai nama disimpan mengikut kedudukan yang dimilikinya ketika itu. Klik satu untuk membukanya dalam penyunting peraturan.',
  'detail.openRule': 'Buka dalam penyunting peraturan',
  'detail.noRules': 'Tiada peraturan menyentuh pautan ini.',
  'detail.player': 'Main',
  'detail.play': 'Mainkan di sini',
  'detail.playHint': 'Memainkan fail terus dari instans ini, tanpa memuat turunnya kali kedua. Tiada apa-apa diambil sehingga anda menekan main, dan fail itu kekal di tempatnya.',
  'detail.playPartial': 'Muat turun ini belum siap. Hanya bahagian yang sudah ada pada cakera boleh dimainkan, melompat melepasinya tidak akan menjadi, dan sesetengah fail tidak memainkan apa-apa langsung sebelum bait terakhir sampai.',
  'detail.playUnsupported': 'Pelayar ini tidak dapat memainkan fail ini. Buka atau simpan ia melalui menu klik kanan sebaliknya.',
  'detail.playRemote': 'Hanya fail pada instans ini boleh dimainkan di sini. Instans lain menyerahkan failnya sekali gus dan tanpa lompatan, dan sebuah pemain tidak boleh bekerja dengan itu.',
  'detail.playNotLocal': 'JDownloader yang mengambil muat turun ini, jadi fail itu berada pada cakera proses tersebut dan bukan pada cakera ini.',
  'detail.playNoFile': 'Belum ada apa-apa pada cakera untuk dimainkan.',
