  'settings.rules.notFound': 'Tiada peraturan di sini yang bernama “{name}”. Ia dinamakan semula atau dipadam sejak pautan yang menamakannya ditambah.',

  'notifications.title': 'Pemberitahuan',
  'notifications.titleHint': 'Tentukan bagi setiap peristiwa sama ada ia muncul sebagai gelembung dalam aplikasi, sebagai pemberitahuan daripada sistem pengendalian anda, atau tidak langsung. Pemberitahuan sistem hanya sampai kepada anda selagi satu tab KnightLoader terbuka, dan mod senyap di bawah tetap terpakai di atasnya.',
  'notifications.channel.app': 'Dalam aplikasi',
  'notifications.channel.system': 'Pemberitahuan sistem',
  'notifications.channel.silent': 'Jangan tunjuk apa-apa',
  'notifications.event.downloadDone': 'Muat turun selesai',
  'notifications.event.downloadDoneHint': 'Setiap muat turun yang sampai ke penghujung akan melaporkannya. Dua ratus fail dalam baris gilir bermakna dua ratus pemberitahuan begini, jadi fikir dua kali sebelum anda menghantarnya ke sistem.',
  'notifications.event.downloadFailed': 'Muat turun gagal',
  'notifications.event.downloadFailedHint': 'Muat turun yang sudah mengalah. Mod senyap tidak pernah menyembunyikan yang ini.',
  'notifications.event.extractionDone': 'Pengekstrakan selesai',
  'notifications.event.extractionDoneHint': 'Arkib yang selesai diekstrak. Ini tidak pernah dilaporkan di mana-mana sebelum ini, jadi ia bermula pada “Jangan tunjuk apa-apa”.',
  'notifications.event.extractionFailed': 'Pengekstrakan gagal',
  'notifications.event.extractionFailedHint': 'Arkib yang berhenti tanpa siap. Kata laluan yang tiada ialah sebab yang biasa, dan fail itu kekal di tempatnya sehingga anda menguruskannya.',
  'notifications.event.captchaWaiting': 'Ada captcha sedang menunggu',
  'notifications.event.captchaWaitingHint': 'Tetingkap captcha tetap terbuka dalam tab ini apa pun keadaannya. Ia bermula pada “Jangan tunjuk apa-apa” kerana tetingkap itu sudah pun menjadi pemberitahuannya selagi anda memandangnya. Tetapkan ia kepada pemberitahuan sistem, dan captcha dalam tab latar belakang akan sampai kepada anda sebelum hoster membuang sesi itu.',
  'notifications.event.captchaFailed': 'Captcha gagal',
  'notifications.event.captchaFailedHint': 'Tiada sesiapa menjawab tepat pada masanya, atau jawapan itu tidak sampai. Muat turun di belakangnya kekal di tempatnya.',
  'notifications.event.captchaResolved': 'Captcha dijawab di tempat lain',
  'notifications.event.captchaResolvedHint': 'Seseorang dalam pelayar lain, atau satu penyelesai automatik, telah menjawabnya, dan tetingkap itu tertutup dengan sendirinya.',
  'notifications.systemUnavailable': 'Pemberitahuan sistem tidak tersedia di sini: pelayar anda hanya menawarkannya melalui HTTPS atau pada localhost. Semua yang ada pada kad ini tetap dipaparkan dalam aplikasi.',
  'notifications.systemBlocked': 'Pelayar anda menyekat pemberitahuan untuk alamat ini. Baris yang ditetapkan kepada “Pemberitahuan sistem” dipaparkan dalam aplikasi sebaliknya, sehingga anda membenarkannya semula dalam tetapan laman pelayar anda.',
  'notifications.systemNotGranted': 'Pelayar tidak memberi kebenaran, jadi peristiwa ini kekal dalam aplikasi. Pilih “Pemberitahuan sistem” sekali lagi untuk bertanya sekali lagi.',
  'notifications.test': 'Hantar ujian',
