  'settings.diagnostics.fix.missing': 'Folder itu tidak ada. Yang terdekat di atasnya yang memang wujud ialah {measured}. Pada mesin yang melekapkan sesuatu perkongsian, ini biasanya bermakna perkongsian itu tidak dilekapkan, dan di sini tiada apa-apa dicipta dengan sengaja: folder yang dibuat di bawah mount yang tiada akan menerima muat turun itu sebaliknya, dan semuanya lenyap dengan kemas kini bekas yang berikutnya.',
  'settings.diagnostics.fix.denied': 'Folder itu ada dan instans ini tidak dibenarkan menulis di dalamnya. Dalam bekas, KnightLoader berjalan sebagai uid 1000, jadi folder itu mesti milik pengguna tersebut atau milik kumpulan yang dianggotainya.',
  'settings.diagnostics.fix.readonly': 'Sistem fail di bawah folder ini dilekapkan sebagai baca sahaja. Tiada apa-apa yang dilakukan oleh instans ini mengubahnya. Lekapan itu yang mesti diubah.',
  'settings.diagnostics.fix.full': 'Sudah tiada ruang lagi pada volum tempat folder ini berada.',
  'settings.diagnostics.fix.notRemoved': 'Fail ujian itu dapat ditulis tetapi tidak dapat dipadam semula. Satu muat turun akan tiba di sini dan kemudian tidak akan pernah dapat dinamakan semula atau dialihkan. Lihat kebenaran padam pada folder itu, bukan kebenaran tulis.',
  'settings.diagnostics.fix.notADir': 'Pada laluan ini ada sebuah fail, bukan sebuah folder.',
  'settings.diagnostics.fix.timeout': 'Folder itu tidak menjawab pada waktunya dan dibiarkan. Perkongsian yang pelayannya mati berkelakuan tepat seperti ini, begitu juga perkongsian pada rangkaian yang sudah hilang.',
  'settings.diagnostics.fix.dataDenied': 'Inilah satu-satunya folder yang instans ini tidak boleh hidup tanpanya: pangkalan data, tetapan dan simpanan akaun yang disulitkan semuanya berada di sini. Muat turun terus berjalan buat masa ini, dan perkara berikutnya yang anda simpan akan hilang.',
  'settings.diagnostics.fix.javaMissing': 'Tiada Java dijumpai. Imej bekas menyertakan satu. Pemasangan desktop menggunakan masa jalan yang disertakan atau satu yang ada pada PATH. Tanpanya, JDownloader peribadi itu tidak bermula, jadi pautan bekas yang disulitkan (.dlc, .ccf, .rsdf) langsung tidak dapat dibuka. Tetapkan JAVA_HOME, atau halakan KL_JD kepada JDownloader yang berjalan di tempat lain.',
  'settings.diagnostics.fix.javaNotNeeded': 'Instans ini tidak memulakan sebarang proses Java miliknya sendiri: sama ada KL_JD menunjuk kepada JDownloader yang berjalan di tempat lain, atau yang peribadi itu dimatikan dengan KL_PROVISION_JD=0.',
  'settings.diagnostics.fix.ytdlpMissing': 'yt-dlp tidak dijumpai (KL_YTDLP, atau “yt-dlp” pada PATH). Halaman media kemudiannya gagal dengan ralat laman itu sendiri dan bukannya dimuat turun.',
  'settings.diagnostics.fix.ffmpegMissing': 'ffmpeg tidak dijumpai. yt-dlp memerlukannya untuk menggabungkan strim gambar dan strim bunyi yang berasingan, yang diberikan oleh kebanyakan laman, jadi satu muat turun berhenti pada salah satu daripada keduanya atau kembali tanpa bunyi.',
  'settings.diagnostics.fix.ffprobeMissing': 'ffprobe tidak dijumpai. Hanya semakan panjang pada video yang siap menggunakannya. Semua yang lain berjalan tanpanya.',
  'settings.diagnostics.fix.notRunnable': 'Dijumpai di {subject} dan ia tidak berjalan: {error}',
  'settings.diagnostics.fix.appearedLate': 'Ia berjalan sekarang, dan ia tiada semasa instans ini bermula, jadi belum ada apa-apa yang dihalakan kepadanya. Mula semula untuk mengambilnya.',
  'settings.diagnostics.fix.utcFallback': 'TZ ditetapkan kepada {subject} dan instans ini tidak dapat memuatkan zon itu, jadi ia berpatah kembali kepada UTC tanpa memberitahu sesiapa. Setiap tetingkap jadual berjalan mengikut UTC sehingga ini dibetulkan. Semak ejaannya dengan senarai zon (“Europe/Berlin”), dan sama ada imej itu memang mempunyai pangkalan data zon.',
  'settings.diagnostics.fix.noZoneDatabase': 'Sistem ini tiada pangkalan data zon, jadi waktu dibaca tanpa sebarang penukaran waktu musim panas langsung. Tetingkap malam mengekalkan jam musim sejuknya sepanjang musim panas, dan tiada apa-apa memberitahu anda apabila ia berlaku.',
  'settings.diagnostics.fix.tzUnset': 'TZ tidak ditetapkan dan tiada waktu tempatan dijumpai, jadi instans ini berjalan mengikut UTC. Itu berfungsi, dan ia patut diketahui: tetingkap jadual yang ditulis sebagai 23:00 bermakna 23:00 UTC, bukan 23:00 di tempat anda.',
  'settings.resolvers.toolsTitle': 'Alat',
