  'settings.resolvers.toolsFfmpegMissingHint': 'Tanpa ffmpeg, yt-dlp tidak dapat menggabungkan trek gambar dan trek bunyi yang berasingan, yang diberikan oleh kebanyakan laman, jadi satu muat turun sama ada mendarat sebagai trek video yang senyap atau terus gagal. Tanpa ffprobe, "Ukur fail yang siap" di bahagian atas halaman ini tidak mengukur apa-apa dan tidak menyatakan apa-apa tentangnya. Dalam bekas, kedua-duanya datang daripada pakej ffmpeg yang dipasang oleh imej itu. Pada desktop anda memasangnya sendiri dan meletakkannya pada PATH.',
  'settings.resolvers.toolsShadowed': 'Salinan KnightLoader sendiri sedang berjalan. Selagi ia ada, KL_YTDLP dan PATH tidak dimulakan: {path} akan digunakan sebaliknya, dan ia melaporkan {version}.',
  'settings.resolvers.toolsShadowedOlder': 'Awas: salinan yang diambil oleh KnightLoader ({current}) lebih lama daripada yang sedia ada pada mesin ini ({system}, di {path}). Kemas kini bekas membawa yt-dlp yang lebih baharu bersamanya, dan salinan anda sendiri tidak ikut bergerak. Ambil yang baharu, atau kembali kepada salinan sistem.',
  'settings.resolvers.toolsManagedBroken': 'Satu salinan yang diambil tercatat di {path} dan ia tidak bermula. Yang berjalan sebaliknya ialah sandaran yang ditunjukkan di atas. Ambilnya semula, atau kembali kepada salinan sistem.',
  'settings.resolvers.toolsActions': 'Memastikan yt-dlp terkini',
